LOGGER = udi_interface.LOGGER


class Controller(udi_interface.Node):
    id = '131313_controller'
    drivers = [{'driver': 'ST', 'value': 0, 'uom': 25, 'name': 'Status'}]
    def __init__(self, polyglot, primary='131313_ctl', address='131313_ctl', name='WeatherAPI Controller'):
        super().__init__(polyglot, primary, address, name)
        self.poly = polyglot
        self.persist_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "persist")
        os.makedirs(self.persist_dir, exist_ok=True)
        # Synchronization for __start()'s wait-for-configDone gate (see __configDoneHandler).
        self.configDone = threading.Condition()
        self.configDoneAlready = False
        self.poly.setCustomParamsDoc('<h2>WeatherAPI</h2>\n<p>Shows current conditions, a multi-day forecast and air quality from <a href="https://www.weatherapi.com/">WeatherAPI.com</a> for <b>one location</b>. Fill in <b>api_key</b> and <b>location</b>, then save. The plugin updates every 15 minutes (the long poll interval) and makes <b>one API call per update</b>.</p>\n\n<h3>api_key (required)</h3>\n<p>Your WeatherAPI.com key. Create a free account at <a href="https://www.weatherapi.com/signup.aspx">weatherapi.com/signup.aspx</a> (no credit card needed), then copy the key from your <a href="https://www.weatherapi.com/my/">account page</a>. Keep it private.</p>\n\n<h3>location (required)</h3>\n<p>Where you want the weather for. WeatherAPI.com accepts:</p>\n<ul>\n<li>A city name, e.g. <code>London</code> or <code>Paris, France</code></li>\n<li>Latitude and longitude, e.g. <code>48.8567,2.3508</code> (the most precise option)</li>\n<li>A US zip code, e.g. <code>10001</code>, or a UK/Canada postcode</li>\n</ul>\n<p>If the location is not found you will see a notice here.</p>\n\n<h3>units</h3>\n<p><code>us</code> (default) reports &deg;F, mph, inHg, inches and miles. <code>metric</code> reports &deg;C, km/h, mb, mm and km. You can change this at any time and the values are re-reported in the new units on the next update (use <b>Refresh Now</b> on the controller to apply it immediately).</p>\n<p><b>Note:</b> if you switch units, review any programs that compare these values against a fixed number (for example "Temperature &gt; 80"), since the number now means something different.</p>\n\n<h3>forecast_days</h3>\n<p>How many forecast nodes to create, from <code>1</code> to <code>14</code> (default <code>3</code>): Today, Tomorrow, Day 3, and so on. Your WeatherAPI.com plan limits how many days are available. If your plan returns fewer days than you asked for, the plugin only creates nodes for the days it received and shows a notice. Lowering the number removes the extra nodes.</p>\n\n<h3>Good to know</h3>\n<ul>\n<li>Air quality uses the US EPA index (Good to Hazardous), plus PM2.5 and PM10 in &micro;g/m&sup3;.</li>\n<li>Condition Code is WeatherAPI.com\'s numeric weather code (for example 1000 = Sunny/Clear). The full list is at <a href="https://www.weatherapi.com/docs/weather-icons/">weatherapi.com/docs/weather-icons</a>.</li>\n<li>Free-plan limits are set by WeatherAPI.com and may change. If you exceed your monthly quota the plugin shows a notice instead of updating.</li>\n</ul>')
        # Additional node classes (current_node, forecast_node) -- construct and self.poly.addNode() them from discover()/start() once their real addresses/names are known (run candidate names/addresses through self.poly.getValidName()/getValidAddress() first).
        self.poly.subscribe(self.poly.START, self.__start, address)
        self.poly.subscribe(self.poly.STOP, self.__stop)
        self.poly.subscribe(self.poly.POLL, self.__poll)
        self.poly.subscribe(self.poly.CONFIG, self.__configHandler)
        self.poly.subscribe(self.poly.CONFIGDONE, self.__configDoneHandler)
        self.poly.subscribe(self.poly.CUSTOMPARAMS, self.parameterHandler)
        self.poly.subscribe(self.poly.CUSTOMNS, self.__customNSHandler)
        self.poly.subscribe(self.poly.CUSTOMDATA, self.__customDataHandler)
        self.poly.subscribe(self.poly.ADDNODEDONE, self.__addNodeDoneHandler)
        self.poly.subscribe(self.poly.DELNODEDONE, self.__removeNodeDoneHandler)
        self.poly.subscribe(self.poly.DISCOVER, self.discover)
        self.poly.subscribe(self.poly.BONJOUR, self.__bonjourHandler)
        self.poly.addNode(self, conn_status='ST')

    def __start(self):
        LOGGER.info("%s: start", self.name)
        try:
            if not self.configDoneAlready:
                with self.configDone:
                    if not self.configDone.wait(timeout=10):
                        LOGGER.error("%s: timed out waiting for configDone", self.name)
                        return
            self.start()
        except Exception as ex:
            LOGGER.error("%s: start failed: %s", self.name, ex)

    def __stop(self):
        LOGGER.info("%s: stop", self.name)
        self.stop()

    def __poll(self, polltype):
        if polltype == "shortPoll":
            self.shortPoll()
        elif polltype == "longPoll":
            self.longPoll()

    def __configHandler(self, config):
        self.processConfig(config)

    def __configDoneHandler(self):
        LOGGER.info("%s: config done", self.name)
        with self.configDone:
            self.configDoneAlready = True
            self.configDone.notifyAll()

    def __addNodeDoneHandler(self, data):
        LOGGER.debug("%s: add node done: %s", self.name, data)

    def __removeNodeDoneHandler(self, data):
        LOGGER.debug("%s: remove node done: %s", self.name, data)

    def __customNSHandler(self, key, data):
        self.customParamHandler(key, data)

    def __customDataHandler(self, data):
        LOGGER.debug("%s: custom data: %s", self.name, data)

    def __bonjourHandler(self, response):
        LOGGER.debug("%s: bonjour: %s", self.name, response)

    # --- developer-authored overrides (edit freely; regeneration preserves them) ---

    def start(self):
        import threading
        st = self.__dict__.setdefault('_wxs', {'cfg': {}, 'nodes': {}, 'lock': threading.Lock(), 'started': False, 'known': set()})
        st['started'] = True
        LOGGER.info('WeatherAPI starting (units=%s, forecast_days=%s)', 'metric' if st['cfg'].get('metric') else 'us', st['cfg'].get('days'))
        self.refresh()

    def stop(self):
        st = self.__dict__.get('_wxs')
        if st:
            st['started'] = False
        LOGGER.info('WeatherAPI stopped')

    def discover(self, *args, **kwargs):
        pass

    def shortPoll(self, *args, **kwargs):
        pass

    def longPoll(self, *args, **kwargs):
        self.refresh()

    def processConfig(self, config):
        import threading
        st = self.__dict__.setdefault('_wxs', {'cfg': {}, 'nodes': {}, 'lock': threading.Lock(), 'started': False, 'known': set()})
        # On a restart, remember which forecast nodes already exist so refresh() can remove extras.
        try:
            nodes = (config or {}).get('nodes') or []
            if isinstance(nodes, dict):
                addrs = list(nodes.keys()) + [n.get('address') for n in nodes.values() if isinstance(n, dict)]
            else:
                addrs = [n.get('address') for n in nodes if isinstance(n, dict)]
            st['known'] = set(a for a in addrs if isinstance(a, str) and a.startswith('fcst_'))
        except Exception as ex:
            LOGGER.error('processConfig: %s', type(ex).__name__)

    def parameterHandler(self, params):
        import threading
        st = self.__dict__.setdefault('_wxs', {'cfg': {}, 'nodes': {}, 'lock': threading.Lock(), 'started': False, 'known': set()})
        params = params or {}
        api_key = str(params.get('api_key') or '').strip()
        location = str(params.get('location') or '').strip()
        units = str(params.get('units') or 'us').strip().lower()
        notes = []
        metric = False
        if units in ('metric', 'si'):
            metric = True
        elif units not in ('us', 'imperial'):
            notes.append("units must be 'us' or 'metric' (you entered '%s'); using 'us'." % units)
        days_raw = str(params.get('forecast_days') or '3').strip()
        try:
            days = int(float(days_raw))
        except ValueError:
            days = 3
            notes.append("forecast_days must be a whole number from 1 to 14 (you entered '%s'); using 3." % days_raw)
        if days < 1 or days > 14:
            days = min(max(days, 1), 14)
            notes.append('forecast_days must be between 1 and 14; using %d.' % days)

        def setn(key, msg):
            try:
                if msg:
                    self.poly.Notices[key] = msg
                else:
                    self.poly.Notices.delete(key)
            except Exception as ex:
                LOGGER.debug('notice %s: %s', key, type(ex).__name__)

        setn('config', None if (api_key and location) else "Enter your WeatherAPI.com api_key and location in the plugin's Custom Parameters, then save.")
        setn('params', ' '.join(notes) if notes else None)

        new = {'api_key': api_key, 'location': location, 'metric': metric, 'days': days}
        changed = new != st['cfg']
        st['cfg'] = new
        # Settings edited while running: refresh right away (off this thread).
        if st['started'] and changed and api_key and location:
            threading.Thread(target=self.refresh, daemon=True).start()

    def customParamHandler(self, *args, **kwargs):
        pass

    def refresh(self, *args, **kwargs):
        import threading
        import requests
        from current_node import CurrentConditions
        from forecast_node import ForecastDay
        st = self.__dict__.setdefault('_wxs', {'cfg': {}, 'nodes': {}, 'lock': threading.Lock(), 'started': False, 'known': set()})
        cfg = st['cfg']
        if not cfg.get('api_key') or not cfg.get('location'):
            return

        def setn(key, msg):
            try:
                if msg:
                    self.poly.Notices[key] = msg
                else:
                    self.poly.Notices.delete(key)
            except Exception as ex:
                LOGGER.debug('notice %s: %s', key, type(ex).__name__)

        with st['lock']:
            cfg = st['cfg']
            try:
                resp = requests.get(
                    'https://api.weatherapi.com/v1/forecast.json',
                    params={'key': cfg['api_key'], 'q': cfg['location'], 'days': cfg['days'], 'aqi': 'yes', 'alerts': 'no'},
                    timeout=20)
            except requests.RequestException as ex:
                # Never log str(ex): the request URL (with the API key) is in it.
                LOGGER.error('WeatherAPI request failed: %s', type(ex).__name__)
                setn('api', 'Could not reach WeatherAPI.com (%s). Will retry on the next update.' % type(ex).__name__)
                return
            try:
                data = resp.json()
            except ValueError:
                data = None
            if not isinstance(data, dict):
                LOGGER.error('WeatherAPI unexpected response, HTTP %s', resp.status_code)
                setn('api', 'WeatherAPI.com returned an unexpected response (HTTP %s).' % resp.status_code)
                return
            err = data.get('error')
            if err:
                code = err.get('code') if isinstance(err, dict) else None
                api_msg = err.get('message', '') if isinstance(err, dict) else str(err)
                friendly = {
                    1002: 'No API key was sent. Set api_key.',
                    2006: 'The API key is invalid. Check api_key.',
                    1006: 'Location not found. Check location.',
                    2007: 'Your monthly WeatherAPI.com call quota is used up.',
                    2008: 'Your WeatherAPI.com API key has been disabled.',
                    2009: "Your WeatherAPI.com plan doesn't allow this request (try a lower forecast_days).",
                }.get(code, 'WeatherAPI.com reported an error.')
                LOGGER.error('WeatherAPI error %s: %s', code, api_msg)
                setn('api', '%s (error %s: %s)' % (friendly, code, api_msg))
                return

            cur = data.get('current') or {}
            fdays = (data.get('forecast') or {}).get('forecastday') or []
            metric = bool(cfg['metric'])
            want = cfg['days']
            n = min(want, len(fdays))
            nodes = st['nodes']

            if 'current' not in nodes:
                node = CurrentConditions(self.poly, self.address, 'current', 'Current Conditions')
                self.poly.addNode(node)
                nodes['current'] = node
            for i in range(1, n + 1):
                addr = 'fcst_%d' % i
                if addr not in nodes:
                    name = 'Today' if i == 1 else ('Tomorrow' if i == 2 else 'Day %d' % i)
                    node = ForecastDay(self.poly, self.address, addr, name)
                    self.poly.addNode(node)
                    nodes[addr] = node
            # Remove forecast nodes beyond the configured/available number of days.
            for addr in set(a for a in nodes if a.startswith('fcst_')) | set(st['known']):
                try:
                    idx = int(addr.split('_', 1)[1])
                except (ValueError, IndexError):
                    continue
                if idx > n:
                    self.poly.delNode(addr)
                    nodes.pop(addr, None)
            st['known'] = set()

            if n < want:
                setn('plan', 'WeatherAPI.com returned %d forecast day(s) but forecast_days is %d. Your plan may limit the forecast length.' % (n, want))
            else:
                setn('plan', None)

            nodes['current'].update(cur, metric)
            for i in range(n):
                nodes['fcst_%d' % (i + 1)].update(fdays[i].get('day') or {}, metric)
            setn('api', None)
            LOGGER.info('WeatherAPI updated for %s: current + %d forecast day(s), %s units', (data.get('location') or {}).get('name', '?'), n, 'metric' if metric else 'US')

    # --- command dispatch (profile cmds.accepts; see udi_interface.Node.runCmd) ---
    commands = {'REFRESH': refresh}
